import { AuthType, EmbedConfig } from '@thoughtspot/visual-embed-sdk';

/** ThoughtSpot worksheet / model GUID for Search, Stella (AI), and Explore embeds */
export const THOUGHTSPOT_MODEL_ID = 'cd252e5c-b552-49a8-821d-3eadaa049cca';

/** Liveboard GUID for LiveboardEmbed (saved dashboard) */
export const THOUGHTSPOT_LIVEBOARD_ID = 'cd408f8e-6f29-4a14-af5f-ddaf57ee04d2';

/** ThoughtSpot Cloud cluster origin (no trailing slash) */
export const thoughtSpotHost = 'https://se-thoughtspot-cloud.thoughtspot.cloud';

export const EMBED_APP_BACKGROUND = '#1C1C1E';
export const TOP_HEADER_PX = 56;
export const VIEWPORT_LESS_TOP_HEADER = `calc(100vh - ${TOP_HEADER_PX}px)`;

const publicBase = process.env.PUBLIC_URL ?? '';
export const DATABOT_ICON_URL = `${publicBase}/databot-robot.svg`;

// ─── Brand palette ────────────────────────────────────────────────────────────
const BRAND_PINK       = '#FF2D55';
const BRAND_PINK_DARK  = '#C9184A';
const BRAND_PINK_LIGHT = '#FFE4EC';
const BRAND_PINK_HOVER = '#FFADC5';
const BRAND_PINK_GLOW  = 'rgba(255,45,85,0.22)';
const APPLE_FONT       = "-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', sans-serif";

// ─── Liveboard dark tile scale ────────────────────────────────────────────────
const LB_DARK          = '#1C1C1E';   // outer layout
const LB_DARK_2        = '#2C2C2E';   // header band
const LB_DARK_3        = '#3A3A3C';   // borders / elevated surfaces
const LB_TILE          = '#484848';   // tile / viz card surface
const LB_TILE_ALT      = '#424242';   // alternating table row
const LB_TILE_HDR      = '#3E3E3E';   // table column headers
const LB_BORDER        = '#555555';   // tile and row borders
const W                = '#ffffff';
const W85              = 'rgba(255,255,255,0.85)';
const W70              = 'rgba(255,255,255,0.70)';
const W55              = 'rgba(255,255,255,0.55)';
const W45              = 'rgba(255,255,255,0.45)';

/**
 * Global init customizations — brand colours and font only.
 * Kept minimal so SearchEmbed and SpotterEmbed keep ThoughtSpot's native light look.
 * Liveboard-specific dark styling is in LIVEBOARD_DARK_CUSTOMIZATIONS below.
 */
const globalStyleVariables: Record<string, string> = {
  '--ts-var-root-font-family':                    APPLE_FONT,
  '--ts-var-application-color':                   BRAND_PINK,

  // Pink filter chips
  '--ts-var-chip-background':                     BRAND_PINK_LIGHT,
  '--ts-var-chip-color':                          BRAND_PINK,
  '--ts-var-chip-border-radius':                  '20px',
  '--ts-var-chip--active-background':             BRAND_PINK,
  '--ts-var-chip--active-color':                  W,
  '--ts-var-chip--hover-background':              BRAND_PINK_HOVER,
  '--ts-var-chip--hover-color':                   BRAND_PINK,
  '--ts-var-chip-title-font-family':              APPLE_FONT,
  '--ts-var-parameter-chip-text-color':           BRAND_PINK,

  // Pink primary buttons
  '--ts-var-button--primary-background':          BRAND_PINK,
  '--ts-var-button--primary-color':               W,
  '--ts-var-button--primary--hover-background':   BRAND_PINK_DARK,
  '--ts-var-button--primary--active-background':  BRAND_PINK_DARK,
  '--ts-var-button--primary--font-family':        APPLE_FONT,
  '--ts-var-button-border-radius':                '24px',
  '--ts-var-button--icon-border-radius':          '50%',

  // Pink menu highlights
  '--ts-var-menu-font-family':                    APPLE_FONT,
  '--ts-var-menu--hover-background':              BRAND_PINK_LIGHT,
  '--ts-var-menu-selected-text-color':            BRAND_PINK,
};

/**
 * Per-embed customizations for LiveboardEmbed only.
 * Pass as the `customizations` prop on every LiveboardEmbed so dark tile
 * styling never bleeds into SearchEmbed or SpotterEmbed.
 */
export const LIVEBOARD_DARK_CUSTOMIZATIONS = {
  style: {
    customCSS: {
      variables: {
        // ── Liveboard layout ────────────────────────────────────────────────
        '--ts-var-liveboard-layout-background':              LB_DARK,
        '--ts-var-liveboard-header-background':              LB_DARK_2,
        '--ts-var-liveboard-header-font-color':              W,
        '--ts-var-liveboard-notetitle-heading-font-color':   W,
        '--ts-var-liveboard-notetitle-body-font-color':      W70,
        '--ts-var-liveboard-tile-background':                LB_TILE,
        '--ts-var-liveboard-tile-border-radius':             '12px',
        '--ts-var-liveboard-tile-border-color':              LB_BORDER,
        '--ts-var-liveboard-group-background':               LB_DARK,
        '--ts-var-liveboard-group-title-font-color':         W,
        '--ts-var-liveboard-group-border-color':             LB_DARK_3,
        '--ts-var-liveboard-group-description-font-color':   W45,
        '--ts-var-liveboard-group-tile-title-font-color':    W,

        // ── Viz tile surfaces ───────────────────────────────────────────────
        '--ts-var-viz-background':                           LB_TILE,
        '--ts-var-viz-border-radius':                        '12px',
        '--ts-var-viz-box-shadow':                           '0 2px 8px rgba(0,0,0,0.3)',
        '--ts-var-viz-title-color':                          W,
        '--ts-var-viz-title-font-family':                    APPLE_FONT,
        '--ts-var-viz-description-color':                    W70,
        '--ts-var-viz-description-font-family':              APPLE_FONT,
        '--ts-var-viz-legend-hover-background':              BRAND_PINK_GLOW,

        // ── Chart axes ─────────────────────────────────────────────────────
        '--ts-var-axis-title-color':                         W70,
        '--ts-var-axis-title-font-family':                   APPLE_FONT,
        '--ts-var-axis-data-label-color':                    W55,
        '--ts-var-axis-data-label-font-family':              APPLE_FONT,

        // ── Menus + dialogs (scoped to liveboard context) ──────────────────
        '--ts-var-menu-color':                               W,
        '--ts-var-menu-background':                          LB_DARK_2,
        '--ts-var-menu-separator-background':                LB_DARK_3,
        '--ts-var-dialog-body-background':                   LB_DARK_2,
        '--ts-var-dialog-body-color':                        W,
        '--ts-var-dialog-header-background':                 LB_DARK,
        '--ts-var-dialog-header-color':                      W,
        '--ts-var-dialog-footer-background':                 LB_DARK_2,

        // ── ag-Grid variables ───────────────────────────────────────────────
        '--ag-background-color':                             LB_TILE,
        '--ag-odd-row-background-color':                     LB_TILE_ALT,
        '--ag-header-background-color':                      LB_TILE_HDR,
        '--ag-foreground-color':                             W85,
        '--ag-data-color':                                   W85,
        '--ag-secondary-foreground-color':                   W55,
        '--ag-header-foreground-color':                      W55,
        '--ag-border-color':                                 LB_BORDER,
        '--ag-row-border-color':                             LB_BORDER,
        '--ag-row-hover-color':                              BRAND_PINK_GLOW,
        '--ag-selected-row-background-color':                BRAND_PINK_GLOW,
        '--ag-range-selection-border-color':                 BRAND_PINK,
        '--ag-input-focus-border-color':                     BRAND_PINK,
        '--ag-checkbox-checked-color':                       BRAND_PINK,
      } as Record<string, string>,
      rules_UNSTABLE: {
        // ── Filter bar padding ───────────────────────────────────────────
        '[class*="filterRow"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
        '[class*="filter-row"]':       { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
        '[class*="compactHeader"]':    { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
        '[class*="compact-header"]':   { 'padding-top': '4px !important', 'padding-bottom': '4px !important', 'min-height': 'unset !important' },
        '[class*="liveboardFilter"]':  { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },
        '[class*="FilterBar"]':        { 'padding-top': '4px !important', 'padding-bottom': '4px !important' },

        // ── ag-Grid class overrides ───────────────────────────────────────
        '.ag-root':                              { 'background-color': '#484848 !important', 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-root-wrapper':                      { 'background-color': '#484848 !important' },
        '.ag-center-cols-container':             { 'background-color': '#484848 !important' },
        '.ag-cell':                              { 'color': 'rgba(255,255,255,0.85) !important', 'border-color': '#555555 !important' },
        '.ag-cell-value':                        { 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-cell-wrapper':                      { 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-group-value':                       { 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-row':                               { 'background-color': '#484848 !important', 'border-color': '#555555 !important' },
        '.ag-row-even':                          { 'background-color': '#484848 !important' },
        '.ag-row-odd':                           { 'background-color': '#424242 !important' },
        '.ag-row:hover':                         { 'background-color': 'rgba(255,45,85,0.2) !important' },
        '.ag-header':                            { 'background-color': '#3E3E3E !important', 'border-color': '#555555 !important' },
        '.ag-header-row':                        { 'background-color': '#3E3E3E !important' },
        '.ag-header-cell':                       { 'background-color': '#3E3E3E !important', 'color': 'rgba(255,255,255,0.55) !important' },
        '.ag-header-cell-label':                 { 'color': 'rgba(255,255,255,0.55) !important' },
        '.ag-header-cell-text':                  { 'color': 'rgba(255,255,255,0.55) !important' },
        '.ag-pinned-left-cols-container .ag-cell':  { 'background-color': '#484848 !important', 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-pinned-right-cols-container .ag-cell': { 'background-color': '#484848 !important', 'color': 'rgba(255,255,255,0.85) !important' },
        '.ag-cell a':                            { 'color': '#FF2D55 !important' },
        '.ag-cell-value a':                      { 'color': '#FF2D55 !important' },
        '.ag-group-value a':                     { 'color': '#FF2D55 !important' },

        // ── Table cells ───────────────────────────────────────────────────
        '[class*="tableCell"]':        { 'color': 'rgba(255,255,255,0.85) !important' },
        '[class*="table-cell"]':       { 'color': 'rgba(255,255,255,0.85) !important' },
        '[class*="headerCell"]':       { 'color': 'rgba(255,255,255,0.55) !important', 'background-color': '#3E3E3E !important' },
        '[class*="agCell"]':           { 'color': 'rgba(255,255,255,0.85) !important' },
        'td':                          { 'color': 'rgba(255,255,255,0.85) !important', 'border-color': '#555555 !important' },
        'th':                          { 'color': 'rgba(255,255,255,0.55) !important', 'background-color': '#3E3E3E !important', 'border-color': '#555555 !important' },

        // ── KPI / headline numbers ────────────────────────────────────────
        '[class*="headlineValue"]':    { 'color': '#ffffff !important' },
        '[class*="kpiValue"]':         { 'color': '#ffffff !important' },
        '[class*="numberValue"]':      { 'color': '#ffffff !important' },
        '[class*="metricValue"]':      { 'color': '#ffffff !important' },
        '[class*="comparisonValue"]':  { 'color': 'rgba(255,255,255,0.7) !important' },

        // ── Legend labels ─────────────────────────────────────────────────
        '[class*="legendLabel"]':      { 'color': 'rgba(255,255,255,0.75) !important' },
        '[class*="legendItem"]':       { 'color': 'rgba(255,255,255,0.75) !important' },

        // ── Tooltip ───────────────────────────────────────────────────────
        '[class*="tooltip"]':          { 'background-color': '#3A3A3C !important', 'color': '#ffffff !important', 'border-color': '#555555 !important' },
        '[class*="tooltipValue"]':     { 'color': '#ffffff !important' },

        // ── Summary / total rows ──────────────────────────────────────────
        '[class*="summaryRow"]':       { 'background-color': '#3E3E3E !important', 'color': 'rgba(255,255,255,0.85) !important' },
        '[class*="totalRow"]':         { 'background-color': '#3E3E3E !important', 'color': '#ffffff !important' },

        // ── Navy link text → pink ─────────────────────────────────────────
        'a':                           { 'color': '#FF2D55 !important' },
        'a:hover':                     { 'color': '#C9184A !important' },
        '[class*="link"]':             { 'color': '#FF2D55 !important' },
        '[class*="Link"]':             { 'color': '#FF2D55 !important' },
        '[class*="attributeValue"]':   { 'color': '#FF2D55 !important' },
        '[class*="cellLink"]':         { 'color': '#FF2D55 !important' },
      },
    },
  },
};

/**
 * SDK init — NoAuth assumes the user is already logged in to ThoughtSpot in the browser.
 */
export function buildThoughtSpotEmbedConfig(): EmbedConfig {
  return {
    thoughtSpotHost,
    authType: AuthType.None,
    suppressSearchEmbedBetaWarning: true,
    customizations: {
      iconSpriteUrl: DATABOT_ICON_URL,
      style: {
        customCSS: {
          variables: globalStyleVariables,
        },
      },
      content: {
        strings: {
          Spotter: 'Stella',
          'AI Highlights': 'Highlights',
          Pin: 'Pin',
        },
      },
    },
  };
}
